import argparse
from dataclasses import asdict, is_dataclass
from pathlib import Path
import json, os, platform, subprocess, sys, time, traceback
import numpy as np
from hipengine import LLM, SamplingParams
from hipengine.benchmark.provenance import collect_artifact_provenance
from scripts.gguf_mtp_category_bench import load_prompt_rows
from scripts.specdec2_perf_gfx1100_child import _output_execution_path, resolve_arm_timing, _latest_scheduler_observability, _latest_route_metadata

def _run_loaded_arm(llm, *, arm, prompt, max_tokens):
    params=SamplingParams(max_tokens=max_tokens,temperature=0.0,top_p=1.0,ignore_eos=False)
    started=time.perf_counter()
    call=llm.generate_detailed if arm=='true_ar' else llm.generate_speculative_mtp_detailed
    output=call((prompt,),params)[0]
    wall=time.perf_counter()-started
    snapshot=llm.live_loop_snapshot()
    return output,wall,_latest_scheduler_observability(snapshot),_latest_route_metadata(snapshot),{}

p=argparse.ArgumentParser(); p.add_argument('--output',required=True); p.add_argument('--runs',type=int,default=2); p.add_argument('--lengths',default='24,128'); p.add_argument('--capacity',type=int,default=1); a=p.parse_args()
model='/models/gguf/Qwen3.6-35B-A3B-UD-Q4_K_M.gguf'
out=Path(a.output);out.parent.mkdir(parents=True,exist_ok=True)
def encode(x):
    if is_dataclass(x): return asdict(x)
    if isinstance(x, np.generic): return x.item()
    if isinstance(x, np.ndarray): return x.tolist()
    if isinstance(x, Path): return str(x)
    raise TypeError(type(x).__name__)
r={'schema':1,'kind':'gguf_public_mtp_current_diagnostic','performance_claim':False,'status':'running','host':platform.node(),'command':[sys.executable,*sys.argv],'protocol':{'model':model,'profile':'production','kv':'bf16','max_active_requests':a.capacity,'prompt_render':'raw public API strings','lengths':[int(n) for n in a.lengths.split(',')],'runs':a.runs,'warmup':'one AR and one MTP 8-token greeting, before measurement','ordering':'alternating AR/MTP by prompt index + run index','sampling':'temperature 0, top_p 1, natural EOS; no candidate-budget override','limitations':['Timing is diagnostic, not a new headline; no strict-teacher or task-quality gate is supplied.','Generated-ID divergence is recorded separately from execution and ownership checks.','Historical llama-compat results are not matched controls.']},'rows':[]}
r['provenance']=collect_artifact_provenance(repo_root=Path.cwd(),configured_backend='hip_gfx1100',resolved_backend='hip_gfx1100',target_arch='gfx1100',model_path=model,quant='gguf_q4_k_m',kv_dtype='bf16',command=r['command'],timing_protocol='counterbalanced whole public API call plus scheduler timing; same-load true AR and MTP',warmups=1,repetitions=a.runs)
def save(): out.write_text(json.dumps(r,indent=2,default=encode)+'\n')
save()
llm=LLM(model,backend='hip_gfx1100',execution_profile='production',max_active_requests=a.capacity,max_sequence_length=2048)
try:
    llm.prepare(max_sequence_length=2048)
    gen=llm._get_text_generator()
    r['resolved_default_budget']=gen.speculative_candidate_budget_default()
    r['manifest']=getattr(llm,'execution_profile_manifest_sha256',None)
    print('loaded; default budget',r['resolved_default_budget'],flush=True)
    for arm in ('true_ar','staged'):
        result=_run_loaded_arm(llm,arm=arm,prompt='Write one short greeting.',max_tokens=8)
        print('warmup',arm,result[1],result[3],flush=True)
    prompts=load_prompt_rows(Path('benchmarks/prompts/mtpbench-code-general-ja.jsonl'))
    for n in r['protocol']['lengths']:
        for run in range(a.runs):
            for i,case in enumerate(prompts):
                pair={'prompt_id':case['id'],'category':case['category'],'prompt':case['prompt'],'max_tokens':n,'run':run,'arms':{}}
                order=('true_ar','staged') if (i+run)%2==0 else ('staged','true_ar')
                for arm in order:
                    value,wall,obs,route,_=_run_loaded_arm(llm,arm=arm,prompt=case['prompt'],max_tokens=n)
                    ids=list(value.generated_token_ids or ())
                    pair['arms'][arm]={'whole_call_s':wall,'output_count':len(ids),'generated_token_ids':ids,'text':value.text,'route':route,'execution_path':_output_execution_path(value),'scheduler_observability':obs,'timing':resolve_arm_timing(complete_request_seconds=wall,output_timing=getattr(value.telemetry,'timing',{}) or {},scheduler_observability=obs),'diagnostics':getattr(value.telemetry,'diagnostics',None),'telemetry':asdict(value.telemetry) if is_dataclass(value.telemetry) else repr(value.telemetry)}
                    if not 0 < len(ids) <= n: raise RuntimeError(f'{case["id"]} {arm} invalid output count {len(ids)} for limit {n}')
                    pair['arms'][arm]['finish_details']=asdict(value.finish_details) if is_dataclass(value.finish_details) else repr(value.finish_details)
                    used=bool(route.get('specdec2_mtp2_used'))
                    if used != (arm=='staged'): raise RuntimeError(f'{case["id"]} {arm} wrong route: {route}')
                ar=pair['arms']['true_ar']['generated_token_ids'];mt=pair['arms']['staged']['generated_token_ids']
                pair['ids_equal']=ar==mt
                pair['first_divergence']=next((j for j,(x,y) in enumerate(zip(ar,mt)) if x!=y),None)
                r['rows'].append(pair);save()
                print(json.dumps({'length':n,'run':run,'id':case['id'],'ids_equal':pair['ids_equal'],'first_divergence':pair['first_divergence'],'ar_s':pair['arms']['true_ar']['whole_call_s'],'mtp_s':pair['arms']['staged']['whole_call_s'],'route':pair['arms']['staged']['route']}),flush=True)
    r['status']='complete'
except Exception as exc:
    r['status']='error';r['error']=f'{type(exc).__name__}: {exc}';traceback.print_exc();raise
finally:
    save()
    llm.close()
